(() => {
  'use strict';
  const KEY='rumpun-orchestra-v1';
  const THEME_KEY='rumpun-theme-v1';
  const tones=['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'];
  const noteLetters=['Do','Di','Re','Ri','Mi','Fa','Fi','Sol','Si♭','La','Li','Ti'];
  const names={beranda:'Ringkasan',pemain:'Pemain',instrumen:'Instrumen',repertoar:'Repertoar',kalender:'Kalender','data':'Ekspor & cadangan'};
  const uid=()=>Math.random().toString(36).slice(2,9);
  const today=()=>new Date().toISOString().slice(0,10);
  const melodiPitches=['F#','G','G#','A','A#','B','C','C#','D','D#','E','F'];
  const melodiPitch=n=>melodiPitches[n%12]+(3+Math.floor((n+6)/12));
  const bassLabels=['g','g#','a','a#','b','c','c#','d','d#','e','f'];
  const gajahLabels=bassLabels.map(x=>x.toUpperCase());
  const bassPitches=['G2','G#2','A2','A#2','B2','C3','C#3','D3','D#3','E3','F3'];
  const gajahPitches=['G1','G#1','A1','A#1','B1','C2','C#2','D2','D#2','E2','F2'];
  const chordLabels=['G','A','B','C','Dm','Em','Fm','G7','A7','A#7','B7','C7','D7','E7','F7','F#7','Bb'];
  const accompName=(size,label)=>'Accomp '+size+' '+label;
  const accompId=(size,label)=>'accomp-'+size.toLowerCase()+'-'+label.toLowerCase().replace('#','sharp').replace('b','flat');
  const idLabel=x=>x.replace('#','s');
  const fresh=()=>({version:9,orchestra:{name:'Orchestra Angklung Saya',conductor:'',location:''},players:[],instruments:[...Array.from({length:36},(_,n)=>({id:'mel-'+n,name:`Melodi ${n}`,family:n<=30?'melodi':'melodiTambahan',number:n,pitch:melodiPitch(n),quantity:1,status:'tersedia',notes:''})),...bassLabels.map(label=>({id:'bass-'+idLabel(label),name:`Bass ${label}`,family:'bass',number:label,pitch:bassPitches[bassLabels.indexOf(label)],quantity:1,status:'tersedia',notes:''})),...gajahLabels.map((label,index)=>({id:'gajah-'+idLabel(label),name:`Gajah ${label}`,family:'gajah',number:label,pitch:gajahPitches[index],quantity:1,status:'tersedia',notes:''})),...['Besar','Kecil'].flatMap(size=>chordLabels.map(label=>({id:accompId(size,label),name:accompName(size,label),family:'chord',number:label,pitch:'',quantity:1,status:'tersedia',notes:(label.endsWith('7')||label==='Bb')?'Akor dominan septim · 4 tabung.':'Akor triad mayor/minor · 3 tabung.'})))],songs:[],events:[]});
  function upgradeData(input){const data={...fresh(),...input},oldVersion=Number(input.version)||1,remap=new Map();data.players=Array.isArray(data.players)?data.players:[];data.songs=Array.isArray(data.songs)?data.songs:[];data.events=Array.isArray(data.events)?data.events:[];data.instruments=Array.isArray(data.instruments)?data.instruments:[];if(oldVersion<2){data.instruments=data.instruments.map(i=>{if(i.family==='melodi'){const n=Number(i.number??String(i.id).replace('mel-',''));const oldPitch=tones[n%12]+(3+Math.floor(n/12));if(Number.isInteger(n)&&i.name===`Melodi ${n}`&&i.pitch===oldPitch)return {...i,pitch:melodiPitches[n%12]};return i}const oldBass=String(i.id||'').match(/^bas-(\d+)$/);if(i.family==='bass'&&oldBass){const n=Number(oldBass[1]),label=bassLabels[n-1];if(label&&i.name===`Bass ${n}`){const id='bass-'+idLabel(label);remap.set(i.id,id);return {...i,id,name:`Bass ${label}`,number:label,pitch:label.toUpperCase()}}}if(i.family==='gajah'&&i.id==='gajah-1'&&i.name==='Angklung Gajah'){const id='gajah-'+idLabel(gajahLabels[0]);remap.set(i.id,id);return {...i,id,name:`Gajah ${gajahLabels[0]}`,number:gajahLabels[0],pitch:gajahLabels[0]}}return i});data.songs.forEach(s=>s.instrumentIds=(s.instrumentIds||[]).map(id=>remap.get(id)||id))}data.players.forEach(p=>{const old=p.instrumentAssignments||Object.fromEntries((p.instrumentIds||[]).map(id=>[id,1]));p.instrumentAssignments=Object.fromEntries(Object.entries(old).map(([id,q])=>[remap.get(id)||id,Math.max(1,Number(q)||1)]));delete p.instrumentIds});if(oldVersion<4){data.instruments=data.instruments.map(i=>{if(i.family!=='melodi')return i;const n=Number(i.number??String(i.id).replace('mel-',''));if(!Number.isInteger(n))return i;if(n>30&&i.name===`Melodi ${n}`)return {...i,family:'lainnya',name:`Melodi ekstra ${n}`,number:`Ekstra ${n}`,notes:(i.notes?i.notes+' · ':'')+'Disimpan dari bank lama; di luar standar melodi 0–30.'};if(n>=0&&n<=30&&i.name===`Melodi ${n}`){const oldPitch=tones[n%12]+(3+Math.floor(n/12));if([melodiPitches[n%12],oldPitch,melodiPitch(n)].includes(i.pitch))return {...i,pitch:melodiPitch(n)}}return i});const known=new Set(data.instruments.map(i=>i.id));fresh().instruments.forEach(i=>{if(!known.has(i.id))data.instruments.push(i)})}data.instruments.forEach(i=>{if(!Number.isFinite(Number(i.quantity))||Number(i.quantity)<1)i.quantity=1});data.events.forEach(e=>{if(!e.attendance||typeof e.attendance!=='object')e.attendance={}});if(oldVersion<5){data.instruments=data.instruments.map(i=>{if(i.family==='bass'){const label=String(i.number??'').toLowerCase(),index=bassLabels.indexOf(label);if(index>=0&&[label.toUpperCase(),bassPitches[index]].includes(i.pitch))return {...i,pitch:bassPitches[index]}}if(i.family==='gajah'){const label=String(i.number??'').toUpperCase(),index=gajahLabels.indexOf(label);if(index>=0&&[label,gajahPitches[index]].includes(i.pitch))return {...i,pitch:gajahPitches[index]}}return i})}if(oldVersion<8){data.instruments=data.instruments.map(i=>{if(i.family==='gajah'&&/^Angklung Gajah/.test(i.name||''))return {...i,name:i.name.replace(/^Angklung Gajah/,'Gajah')};const m=String(i.name||'').match(/^Melodi (?:ekstra )?(3[1-5])$/i),n=m?Number(m[1]):Number(i.number);if(n>=31&&n<=35&&(i.family==='lainnya'||i.family==='melodi'||i.family==='melodiTambahan'))return {...i,family:'melodiTambahan',name:'Melodi '+n,number:n,pitch:melodiPitch(n)};return i});const known=new Set(data.instruments.map(i=>i.id));fresh().instruments.filter(i=>i.family==='melodiTambahan').forEach(i=>{if(!known.has(i.id))data.instruments.push(i)})}data.instruments=data.instruments.map(i=>{if(i.family!=='chord')return i;const label=chordLabels.find(x=>x.toLowerCase()===String(i.number||'').trim().toLowerCase());if(!label){const copy={...i};delete copy.size;return copy}const oldSize=String(i.size||'').toLowerCase(),size=oldSize==='besar'||/besar/i.test(i.name||'')?'Besar':oldSize==='kecil'||/kecil/i.test(i.name||'')?'Kecil':'';const copy={...i,name:size?accompName(size,label):i.name,number:label,notes:i.notes|| ((label.endsWith('7')||label==='Bb')?'Akor dominan septim · 4 tabung.':'Akor triad mayor/minor · 3 tabung.')};delete copy.size;return copy});const standardAccomp=fresh().instruments.filter(i=>i.family==='chord');standardAccomp.forEach(instrument=>{if(!data.instruments.some(i=>i.family==='chord'&&i.number===instrument.number&&i.name===instrument.name))data.instruments.push(instrument)});data.version=9;if(oldVersion<9){try{localStorage.setItem(KEY,JSON.stringify(data))}catch(e){console.warn('Could not save migrated orchestra data',e)}}return data}
  function load(){try{const saved=localStorage.getItem(KEY);if(saved){const data=JSON.parse(saved);if(data&&Array.isArray(data.players)&&Array.isArray(data.instruments))return upgradeData(data);}}catch(e){console.warn('Local data could not be read',e)}return fresh()}
  let db=load(),page='beranda',month=new Date(),playerQuery='',songQuery='',instrumentFilter='semua',instrumentGroup='set-angklung',calendarView='calendar';
  const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
  function applyTheme(theme){const current=theme==='dark'?'dark':'light';document.documentElement.dataset.theme=current;const button=$('#themeToggle');if(button){button.textContent=current==='dark'?'☼':'◐';button.title=current==='dark'?'Ganti ke tema terang':'Ganti ke tema gelap';button.setAttribute('aria-label',current==='dark'?'Aktifkan tema terang':'Aktifkan tema gelap')}const meta=$('meta[name="theme-color"]');if(meta)meta.content=current==='dark'?'#141d18':'#f5f5ef'}
  function toggleTheme(){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem(THEME_KEY,next)}catch(e){console.warn('Tema tidak dapat disimpan',e)}applyTheme(next)}
  let initialTheme='light';try{initialTheme=localStorage.getItem(THEME_KEY)==='dark'?'dark':'light'}catch(e){}applyTheme(initialTheme);
  function save(){localStorage.setItem(KEY,JSON.stringify(db));const status=$('#savedStatus');if(status)status.textContent='Terakhir disimpan '+new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});renderNavCounts()}
  function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function toast(msg,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2600)}
  const byId=(arr,id)=>arr.find(x=>x.id===id);
  function renderNavCounts(){$('#playerNavCount').textContent=db.players.length;$('#instrumentNavCount').textContent=db.instruments.length;$('#songNavCount').textContent=db.songs.length}
  function setPage(next){page=next;$('#sidebar').classList.remove('open');render()}
  function head(eyebrow,title,desc,button=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}
  function actionBtn(label,onclick,cls='btn btn-primary',icon='+'){return `<button class="${cls}" onclick="${onclick}"><span>${icon}</span>${label}</button>`}
  function empty(icon,title,desc,action=''){return `<div class="empty-state"><div class="empty-icon">${icon}</div><b>${title}</b>${desc}${action?`<div style="margin-top:13px">${action}</div>`:''}</div>`}
  function render(){renderNavCounts();$('#pageCrumb').textContent=names[page];$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const root=$('#pageContent');root.innerHTML=({beranda:home,pemain:players,instrumen:instruments,repertoar:songs,kalender:calendar,data:dataPage}[page])();bindPageEvents()}
  function home(){const coming=[...db.events].filter(e=>e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4),recent=[...db.songs].slice(-4).reverse();return `${head('ORCHESTRA WORKSPACE',`Halo, ${esc(db.orchestra.name)}!`,'Satu ruang untuk pemain, instrumen, repertoar, dan latihan.',actionBtn('Tambah data','openQuickAdd()'))}<section class="hero"><div class="hero-copy"><div class="eyebrow">MUSIK KITA, DIKELOLA BERSAMA</div><h2>Latihan lebih teratur,<br>orkestra lebih kompak.</h2><p>Semua catatan orchestra tersimpan aman di perangkat ini.</p></div><div class="hero-note">♫</div><button class="btn" onclick="setPage('kalender')">▦ &nbsp;Buka kalender latihan</button></section><section class="stats-grid"><div class="stat-card"><div><label>Pemain terdaftar</label><strong>${db.players.length}</strong></div><span class="stat-icon">♧</span></div><div class="stat-card"><div><label>Unit angklung</label><strong>${db.instruments.reduce((sum,i)=>sum+Number(i.quantity||1),0)}</strong></div><span class="stat-icon">♫</span></div><div class="stat-card"><div><label>Lagu di repertoar</label><strong>${db.songs.length}</strong></div><span class="stat-icon">▤</span></div><div class="stat-card"><div><label>Jadwal mendatang</label><strong>${coming.length}</strong></div><span class="stat-icon">▦</span></div></section><div class="columns"><section class="panel"><div class="panel-head"><h3>Latihan berikutnya</h3><button class="text-link" onclick="setPage('kalender')">Lihat kalender →</button></div>${coming.length?coming.map(e=>`<div class="list-row"><div class="row-avatar">${dateNum(e.date)}</div><div class="row-main"><b>${esc(e.title)}</b><small>${prettyDate(e.date)} · ${esc(e.time||'Waktu belum ditentukan')} · ${esc(e.location||'Lokasi belum ditentukan')} · ${esc(attendanceSummary(e))}</small></div><span class="pill ${e.type==='performance'?'gold':''}">${eventType(e.type)}</span></div>`).join(''):empty('▦','Belum ada jadwal','Buat jadwal latihan atau penampilan pertama.',actionBtn('Tambah jadwal',"openEventForm()",'btn btn-sm btn-quiet','+'))}</section><section class="panel"><div class="panel-head"><h3>Repertoar terbaru</h3><button class="text-link" onclick="setPage('repertoar')">Lihat semua →</button></div>${recent.length?recent.map(s=>`<div class="list-row"><div class="row-avatar">♫</div><div class="row-main"><b>${esc(s.title)}</b><small>${esc(s.composer||'Komposer belum diisi')} · Do=${esc(s.doKey||'C')}</small></div><span class="pill">${s.notes?.length||0} baris notasi</span></div>`).join(''):empty('♫','Repertoar masih kosong','Tambahkan lagu dan notasi angklung.',actionBtn('Tambah lagu',"openSongForm()",'btn btn-sm btn-quiet','+'))}</section></div><div class="footer-note">Tip: ekspor XML berkala untuk menyimpan salinan data orchestra.</div>`}
  const assignedQty=(p,id)=>Number(p.instrumentAssignments?.[id]||((p.instrumentIds||[]).includes(id)?1:0));
  const inventoryAssigned=(id,exceptPlayer='')=>db.players.reduce((sum,p)=>sum+(p.id===exceptPlayer?0:assignedQty(p,id)),0);
  const instrumentsFor=p=>db.instruments.filter(i=>assignedQty(p,i.id)>0);
  function players(){const list=db.players.filter(p=>`${p.name} ${p.section||''} ${p.email||''}`.toLowerCase().includes(playerQuery.toLowerCase()));return `${head('PEOPLE & ROLES','Pemain','Kelola anggota dan jumlah angklung yang mereka pegang.',actionBtn('Tambah pemain',"openPlayerForm()"))}<section class="panel"><div class="toolbar"><label class="search"><span>⌕</span><input id="playerSearch" placeholder="Cari nama atau bagian..." value="${esc(playerQuery)}"></label><span class="pill gray">${db.players.length} anggota</span></div>${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>PEMAIN</th><th>BAGIAN</th><th>INSTRUMEN DIPEGANG</th><th>KONTAK</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="table-name">${esc(p.name)}</div><div class="table-sub">${esc(p.pronouns||'')}</div></td><td>${esc(p.section||'—')}</td><td>${instrumentsFor(p).length?`<div class="player-instrument-list">${instrumentsFor(p).map(i=>playerInstrumentDetail(p,i)).join('')}</div>`:'<span class="table-sub">Belum ditentukan</span>'}</td><td>${esc(p.email||p.phone||'—')}</td><td><div class="actions"><button class="btn btn-icon" title="Edit" onclick="openPlayerForm('${p.id}')">✎</button><button class="btn btn-icon btn-danger" title="Hapus" onclick="deletePlayer('${p.id}')">×</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('♧',playerQuery?'Tidak ada hasil':'Belum ada pemain',playerQuery?'Coba kata pencarian lain.':'Tambahkan pemain dan tetapkan instrumen yang mereka pegang.',playerQuery?'':actionBtn('Tambah pemain',"openPlayerForm()",'btn btn-sm btn-quiet','+'))}</section>`}
  function instruments(){const groups=[['set-angklung','Set Angklung'],['altam','Alat Tambahan (AlTam)']],familyFilters=[['semua','Semua'],['melodi','Melodi 0–30'],['melodiTambahan','Melodi tambahan 31–35'],['bass','Bass'],['gajah','Gajah'],['chord','Accomp (Chord)']],bankFamilies=['melodi','melodiTambahan','bass','gajah','chord'],inGroup=i=>instrumentGroup==='altam'?!bankFamilies.includes(i.family):bankFamilies.includes(i.family),list=db.instruments.filter(i=>inGroup(i)&&(instrumentGroup==='altam'||instrumentFilter==='semua'||i.family===instrumentFilter)),actions=actionBtn(instrumentGroup==='altam'?'Tambah AlTam':'Tambah instrumen set',instrumentGroup==='altam'?"openInstrumentForm('', 'altam')":"openInstrumentForm()",'btn btn-quiet','+')+(instrumentGroup==='set-angklung'?actionBtn('Tambah Accomp',"openInstrumentForm('', 'chord')",'btn btn-quiet','+')+actionBtn('Peta nada melodi',"editBankNotes()",'btn btn-primary','♫'):'');const intro=instrumentGroup==='altam'?'<b>Alat Tambahan (AlTam):</b> Instrumen di luar set angklung, misalnya Contrabass, Violin, dan Gitar. Tambahkan alat yang dimiliki, lalu catat pemain dan jumlah unitnya.':'<b>Set Angklung:</b> Melodi 0–30: F#3–C6; Melodi tambahan 31–35: C#6–F6. Bass g–f: G2–F3; Gajah G–F: G1–F2. Set pengiring mencakup Accomp Besar (wilayah rendah) dan Accomp Kecil (wilayah lebih tinggi), masing-masing tersedia untuk 17 akor standar. Triad mayor/minor memakai 3 tabung; akor dominan 7 memakai 4 tabung. Kurulung menahan bunyi, cetok memberi aksen pendek, dan tangkep menahan tabung ke-7 saat partitur meminta triad.';return head('INSTRUMENT BANK','Instrumen','Kelola terpisah set angklung dan alat tambahan.',actions)+'<div class="filter-row">'+groups.map(g=>'<button class="filter-chip '+(instrumentGroup===g[0]?'active':'')+'" data-instrument-group="'+g[0]+'">'+g[1]+'</button>').join('')+'</div><div class="inventory-intro">'+intro+'</div>'+(instrumentGroup==='set-angklung'?'<div class="filter-row">'+familyFilters.map(f=>'<button class="filter-chip '+(instrumentFilter===f[0]?'active':'')+'" data-filter="'+f[0]+'">'+f[1]+'</button>').join('')+'</div>':'')+'<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>INSTRUMEN</th><th>LABEL</th><th>NADA MUTLAK / PITCH</th><th>PERSEDIAAN / DIPEGANG / TERSEDIA</th><th>PEMEGANG</th><th>KONDISI</th><th></th></tr></thead><tbody>'+(list.map(i=>{const assigned=inventoryAssigned(i.id),available=Math.max(0,Number(i.quantity||1)-assigned),holders=db.players.filter(p=>assignedQty(p,i.id)>0);return '<tr><td><div class="table-name">'+esc(i.name)+'</div>'+(i.notes?'<div class="table-sub">'+esc(i.notes)+'</div>':'')+'</td><td><span class="pill gray">'+esc(i.number??'—')+'</span></td><td>'+esc(i.pitch||(i.family==='chord'?i.number:'—'))+'</td><td><b>'+Number(i.quantity||1)+'</b> / '+assigned+' / '+available+'</td><td>'+(holders.length?holders.map(p=>esc(p.name)+' ×'+assignedQty(p,i.id)).join('<br>'):'<span class="table-sub">Belum ditetapkan</span>')+'</td><td><span class="pill '+(i.status==='perbaikan'?'gold':'')+'">'+(i.status==='perbaikan'?'Perlu perbaikan':i.status==='dipinjam'?'Dipinjam':'Tersedia')+'</span></td><td><div class="actions"><button class="btn btn-icon" title="Edit" onclick="openInstrumentForm(\''+i.id+'\')">✎</button>'+(!bankFamilies.includes(i.family)?'<button class="btn btn-icon btn-danger" onclick="deleteInstrument(\''+i.id+'\')">×</button>':'')+'</div></td></tr>'}).join('')||'<tr><td colspan="7"><div class="empty-state"><b>Belum ada instrumen di kategori ini</b>Tambahkan alat untuk mulai mengelola persediaan dan pemainnya.</div></td></tr>')+'</tbody></table></div></section>'}
  function songs(){const list=db.songs.filter(s=>`${s.title} ${s.composer||''}`.toLowerCase().includes(songQuery.toLowerCase())),groups=new Map();list.forEach(s=>{const key=String(s.doKey||'C').trim()||'C';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s)});const rows=[...groups].map(([key,items])=>`<tr class="repertoire-key-group"><td colspan="5"><b>Do=${esc(key)}</b><span>${[...new Set(items.map(s=>s.scale||'diatonis'))].map(esc).join(' / ')} · ${items.length} lagu</span></td></tr>${items.map(s=>`<tr><td><div class="table-name">${esc(s.title)}</div><div class="table-sub">${esc(s.genre||'')}</div></td><td>${esc(s.composer||'—')}</td><td>${songInstrumentSummary(s)}</td><td>${s.notes?.length||0} baris</td><td><div class="actions"><button class="btn btn-icon" title="Lihat notasi" onclick="viewSong('${s.id}')">⌕</button><button class="btn btn-icon" title="Edit" onclick="openSongForm('${s.id}')">✎</button><button class="btn btn-icon btn-danger" title="Hapus" onclick="deleteSong('${s.id}')">×</button></div></td></tr>`).join('')}`).join('');return `${head('MUSIC LIBRARY','Repertoar','Lagu dikelompokkan menurut Do= agar nada dasar yang sama tampil sekali.',actionBtn('Tambah lagu',"openSongForm()"))}<section class="panel"><div class="toolbar"><label class="search"><span>⌕</span><input id="songSearch" placeholder="Cari judul atau komposer..." value="${esc(songQuery)}"></label><span class="pill gray">${list.length} lagu</span></div>${list.length?`<div class="table-wrap"><table class="data-table repertoire-table"><thead><tr><th>JUDUL LAGU</th><th>KOMPOSER</th><th>INSTRUMEN / PART</th><th>NOTASI</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('▤',songQuery?'Tidak ada hasil':'Belum ada lagu tersimpan',songQuery?'Coba kata pencarian lain.':'Tambahkan lagu, tetapkan Do= dan catat notasinya.',songQuery?'':actionBtn('Tambah lagu',"openSongForm()",'btn btn-sm btn-quiet','+'))}</section>`}
  function addDaysISO(date,days){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
  function addMonthsISO(date,months){const [y,m,day]=date.split('-').map(Number),target=new Date(Date.UTC(y,m-1+months,1)),last=new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth()+1,0)).getUTCDate();return target.getUTCFullYear()+'-'+String(target.getUTCMonth()+1).padStart(2,'0')+'-'+String(Math.min(day,last)).padStart(2,'0')}
  function dateDistance(from,to){return Math.round((Date.parse(to+'T00:00:00Z')-Date.parse(from+'T00:00:00Z'))/86400000)}
  function recurrenceDates(start,frequency,until){const dates=[start];for(let n=1;n<500;n++){const d=frequency==='monthly'?addMonthsISO(start,n):addDaysISO(start,n*(frequency==='biweekly'?14:7));if(d>until)break;dates.push(d)}return dates}
  function performanceOverviewMarkup(){const shows=db.events.filter(e=>e.type==='performance'&&e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)),next=shows[0];if(!next)return '<section class="panel performance-overview"><div class="panel-head"><h3>Persiapan pertunjukan</h3><span class="pill gray">Belum ada penampilan</span></div><p class="help-text">Tambahkan jadwal penampilan untuk melihat hitung mundur dan jumlah latihan yang tersisa.</p></section>';const rehearsals=db.events.filter(e=>e.type==='rehearsal'&&e.date>=today()&&e.date<next.date),days=dateDistance(today(),next.date),close=[];for(let i=1;i<shows.length;i++){const gap=dateDistance(shows[i-1].date,shows[i].date);if(gap<=14)close.push({a:shows[i-1],b:shows[i],gap})}return '<section class="panel performance-overview"><div class="panel-head"><h3>Persiapan pertunjukan berikutnya</h3><span class="pill gold">'+(days===0?'Hari ini':days+' hari lagi')+'</span></div><div class="performance-next"><div><b>'+esc(next.title)+'</b><small>'+esc(prettyDate(next.date))+' · '+esc(next.time||'waktu belum ditentukan')+'</small></div><div class="rehearsal-count"><strong>'+rehearsals.length+'</strong><span>latihan terjadwal<br>sebelum tampil</span></div></div><p class="help-text">'+(rehearsals.length===0?'Belum ada latihan terjadwal sebelum pertunjukan ini.':rehearsals.length===1?'Ada 1 latihan terjadwal sebelum pertunjukan.':'Ada '+rehearsals.length+' latihan terjadwal sebelum pertunjukan.')+' Jumlah ini membantu melihat waktu persiapan; kecukupan latihan bergantung pada materi orchestra.</p>'+(close.length?'<div class="schedule-alert"><b>Penampilan berdekatan (selisih ≤14 hari)</b>'+close.slice(0,3).map(x=>'<div>'+esc(x.a.title)+' ('+esc(prettyDate(x.a.date))+') → '+esc(x.b.title)+' ('+esc(prettyDate(x.b.date))+'): '+x.gap+' hari</div>').join('')+'</div>':'')+'</section>'}
  function eventSeries(item,frequency,until,seriesId,preserve){return recurrenceDates(item.date,frequency,until).map((date,index)=>{const previous=preserve.find(e=>e.date===date);return {...item,id:previous?.id||(index===0?item.id:uid()),date,attendance:previous?.attendance||{},recurrence:{seriesId,frequency,until,index}}})}
  function attendanceSummary(e){const values=Object.values(e.attendance||{});const present=values.filter(v=>v==='hadir').length;return present+'/'+db.players.length+' hadir'+(values.length?' · '+values.length+' ditandai':' · belum diabsen')}
  function timelineView(){const list=[...db.events].sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||''));return performanceOverviewMarkup()+'<div class="timeline">'+(list.length?list.map(e=>'<article class="timeline-item '+(e.type==='performance'?'milestone':'')+'"><div class="timeline-marker"></div><div class="timeline-card"><div class="timeline-date">'+esc(prettyDate(e.date))+' · '+esc(e.time||'waktu belum ditentukan')+'</div><div class="timeline-title-row"><h3>'+esc(e.title)+'</h3><span class="pill '+(e.type==='performance'?'gold':'')+'">'+eventType(e.type)+'</span></div><div class="timeline-meta">'+esc(e.location||'Lokasi belum ditentukan')+' · '+esc(attendanceSummary(e))+'</div>'+(e.description?'<p>'+esc(e.description)+'</p>':'')+'<div class="timeline-actions"><button class="btn btn-sm btn-quiet" onclick="openAttendance(\''+e.id+'\')">Absensi</button><button class="btn btn-sm" onclick="openEventForm(\''+e.id+'\')">Edit</button></div></div></article>').join(''):'<div class="empty-state"><div class="empty-icon">↗</div><b>Timeline masih kosong</b>Tambahkan jadwal latihan dan tanggal pertunjukan untuk menyusun rangkaiannya.</div>')+'</div>'}
  function calendar(){const year=month.getFullYear(),m=month.getMonth(),first=new Date(year,m,1),start=(first.getDay()+6)%7,days=new Date(year,m+1,0).getDate(),prevDays=new Date(year,m,0).getDate(),monthName=month.toLocaleDateString('id-ID',{month:'long',year:'numeric'});let cells='';for(let n=0;n<42;n++){let day,date,muted=false;if(n<start){day=prevDays-start+n+1;date=new Date(year,m-1,day);muted=true}else if(n>=start+days){day=n-start-days+1;date=new Date(year,m+1,day);muted=true}else{day=n-start+1;date=new Date(year,m,day)}let iso=date.toISOString().slice(0,10),items=db.events.filter(e=>e.date===iso);cells+='<div class="cal-day '+(muted?'muted ':'')+(iso===today()?'today':'')+'" data-date="'+iso+'" title="Klik untuk menambah jadwal"><div class="day-number">'+day+'</div>'+items.slice(0,2).map(e=>'<div class="cal-event '+(e.type==='performance'?'performance':e.type==='other'?'other':'')+'" data-event="'+e.id+'" title="'+esc(e.title)+'">'+esc(e.time?e.time+' ':'')+esc(e.title)+(e.recurrence?' · ↻':'')+'</div>').join('')+(items.length>2?'<div class="cal-event other">+'+(items.length-2)+' lainnya</div>':'')+'</div>'}const toggle='<div class="view-toggle"><button class="filter-chip '+(calendarView==='calendar'?'active':'')+'" data-calendar-view="calendar">Kalender</button><button class="filter-chip '+(calendarView==='timeline'?'active':'')+'" data-calendar-view="timeline">Timeline</button></div>';const heading=head('PLAN & REHEARSE','Kalender orchestra','Jadwal latihan, absensi pemain, dan perjalanan menuju pertunjukan.',actionBtn('Tambah jadwal',"openEventForm()"));if(calendarView==='timeline')return heading+'<section class="panel"><div class="panel-head"><h3>Rangkaian latihan & pertunjukan</h3>'+toggle+'</div>'+timelineView()+'</section>';return heading+'<section class="panel"><div class="panel-head"><div class="calendar-toolbar"><button class="btn btn-icon" id="prevMonth">‹</button><h2>'+monthName+'</h2><button class="btn btn-icon" id="nextMonth">›</button><button class="btn btn-sm btn-quiet" id="todayMonth">Hari ini</button></div>'+toggle+'</div><div class="calendar-grid">'+['SEN','SEL','RAB','KAM','JUM','SAB','MIN'].map(d=>'<div class="cal-weekday">'+d+'</div>').join('')+cells+'</div><div class="calendar-note">Pilih tanggal untuk membuat agenda. Pilih acara untuk membuka detail dan absensi.</div></section><section class="panel" style="margin-top:16px"><div class="panel-head"><h3>Agenda bulan ini</h3><span class="pill gray">'+db.events.filter(e=>e.date.startsWith(year+'-'+String(m+1).padStart(2,'0'))).length+' acara</span></div>'+db.events.filter(e=>e.date.startsWith(year+'-'+String(m+1).padStart(2,'0'))).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>'<div class="list-row"><div class="row-avatar">'+dateNum(e.date)+'</div><div class="row-main"><b>'+esc(e.title)+(e.recurrence?' · ↻':'')+'</b><small>'+esc(prettyDate(e.date))+' · '+esc(e.time||'—')+' · '+esc(e.location||'Lokasi belum ditentukan')+' · '+esc(attendanceSummary(e))+'</small></div><span class="pill '+(e.type==='performance'?'gold':'')+'">'+eventType(e.type)+'</span><button class="btn btn-sm btn-quiet" onclick="openAttendance(\''+e.id+'\')">Absensi</button><button class="btn btn-icon btn-danger" onclick="deleteEvent(\''+e.id+'\')">×</button></div>').join('')||empty('▦','Belum ada agenda bulan ini','Tambahkan jadwal latihan, penampilan, atau agenda lainnya.')+'</section>'}
  function dataPage(){return `${head('PORTABILITY & BACKUP','Data & cadangan','Data disimpan di browser ini. Ekspor salinan untuk dipindah atau dicadangkan.') }<div class="data-grid"><article class="data-card"><div class="data-icon">⇩</div><h3>Ekspor XML orchestra</h3><p>Simpan seluruh orchestra dalam satu berkas XML: pemain, instrumen dan penugasannya, lagu beserta notasi, serta kalender.</p><button class="btn btn-primary" onclick="exportXML()">Unduh berkas XML</button></article><article class="data-card"><div class="data-icon">▧</div><h3>Cadangan JSON</h3><p>Berkas JSON mencakup semua data yang dapat dibaca kembali oleh Rumpun. Cocok untuk cadangan lengkap.</p><button class="btn btn-quiet" onclick="exportJSON()">Unduh cadangan JSON</button></article><article class="data-card"><div class="data-icon">↥</div><h3>Pulihkan dari berkas</h3><p>Impor cadangan XML atau JSON. Data di browser akan digantikan setelah Anda menyetujui.</p><button class="btn btn-quiet" onclick="document.getElementById('importFile').click()">Pilih berkas untuk diimpor</button></article><article class="data-card"><div class="data-icon">✎</div><h3>Identitas orchestra</h3><p>Perbarui nama kelompok, konduktor, dan lokasi utama yang akan tampil di ringkasan.</p><button class="btn btn-quiet" onclick="openOrchestraForm()">Edit informasi orchestra</button></article></div><section class="panel" style="margin-top:15px"><div class="panel-head"><h3>Isi ruang kerja ini</h3><span class="pill gray">Penyimpanan lokal</span></div><div class="list-row"><div class="row-avatar">♧</div><div class="row-main"><b>${db.players.length} pemain</b><small>Nama dan pembagian instrumen</small></div><div class="row-avatar">♫</div><div class="row-main"><b>${db.instruments.length} label · ${db.instruments.reduce((sum,i)=>sum+Number(i.quantity||1),0)} unit</b><small>Nomor, keluarga, nada acuan, alokasi</small></div></div><div class="list-row"><div class="row-avatar">▤</div><div class="row-main"><b>${db.songs.length} lagu</b><small>Do=, nada dasar, notasi dan part</small></div><div class="row-avatar">▦</div><div class="row-main"><b>${db.events.length} agenda</b><small>Latihan dan acara mendatang</small></div></div></section><div class="footer-note">Tidak perlu akun. Berkas ekspor merupakan salinan yang bisa Anda simpan sendiri.</div>`}
  function dateNum(d){return Number(d.slice(-2))}function prettyDate(d){return new Date(d+'T12:00:00').toLocaleDateString('id-ID',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}function eventType(t){return t==='performance'?'Penampilan':t==='other'?'Agenda':'Latihan'}function familyName(f){return f==='melodi'?'Melodi':f==='melodiTambahan'?'Melodi tambahan':f==='bass'?'Bass':f==='gajah'?'Gajah':f==='chord'?'Accomp (Chord)':'Alat Tambahan (AlTam)'}
  function parsePitch(value){const m=String(value||'').trim().match(/^([A-Ga-g])([#♯b♭]?)(-?\d+)?$/);if(!m)return null;const naturals={C:0,D:2,E:4,F:5,G:7,A:9,B:11},letter=m[1].toUpperCase(),accidental=m[2];let pc=naturals[letter],alteration=0;if(accidental==='#'||accidental==='♯'){pc++;alteration=1}if(accidental==='b'||accidental==='♭'){pc--;alteration=-1}return {pc:(pc+12)%12,octave:m[3]===undefined?null:Number(m[3]),letter,alteration}}
  function relativeNotation(instrument,doKey){const note=parsePitch(instrument.pitch||instrument.number),root=parsePitch(doKey);if(!note||!root)return '—';const letters='CDEFGAB',naturalOffsets=[0,2,4,5,7,9,11],degree=(letters.indexOf(note.letter)-letters.indexOf(root.letter)+7)%7,expectedPc=(root.pc+naturalOffsets[degree])%12,alteration=((note.pc-expectedPc+6)%12)-6;let accidental=alteration>0?'/'.repeat(alteration):'\\'.repeat(-alteration),octave='';if(note.octave!==null){const notePosition=note.octave*12+note.pc,doPosition=(root.octave??4)*12+root.pc,expectedInterval=naturalOffsets[degree]+alteration,relativeOctave=Math.floor((notePosition-doPosition-expectedInterval)/12);if(relativeOctave<0)octave='.'.repeat(Math.min(4,Math.abs(relativeOctave)));if(relativeOctave>0)octave='^'.repeat(Math.min(4,relativeOctave))}return String(degree+1)+accidental+octave}
  function noteMapping(instrument,doKey){return 'Mutlak '+(instrument.pitch||'—')+' · Do='+doKey+' → '+relativeNotation(instrument,doKey)}
  function playerInstrumentDetail(p,instrument){const absolute=instrument.pitch||(instrument.family==='chord'?instrument.number:'—'),used=db.songs.filter(s=>(s.instrumentIds||[]).includes(instrument.id)),groups=new Map();used.forEach(song=>{const key=String(song.doKey||'C').trim()||'C';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(song)});const map=[...groups].map(([key,list])=>'<span class="instrument-do-group"><b>Do='+esc(key)+(instrument.family==='chord'?'':'4')+'</b><span>'+(instrument.family==='chord'?'label akor '+esc(instrument.number||'—')+' · ':'')+list.map(song=>esc(song.title)).join(', ')+'</span>'+(instrument.family==='chord'?'':'<em>→ '+relativeNotation(instrument,key)+'</em>')+'</span>').join('');return '<div class="player-instrument"><div class="player-instrument-top"><b>'+esc(instrument.name)+' ×'+assignedQty(p,instrument.id)+'</b><span>'+esc(absolute)+'</span></div>'+(map?'<div class="player-instrument-uses">'+map+'</div>':'<small class="player-instrument-unused">Belum tercatat pada lagu di repertoar.</small>')+'</div>'}
  function songInstrumentDetail(instrument,song){if(instrument.family==='chord')return '<div class="pitch-mapping"><b>'+esc(instrument.name)+' · '+esc(instrument.number||instrument.pitch||'—')+'</b><small>Label chord pada partitur · Do='+esc(song.doKey||'C')+'</small></div>';return '<div class="pitch-mapping"><b>'+esc(instrument.name)+' · '+esc(instrument.pitch||'—')+'</b><small>Do='+esc(song.doKey||'C')+'4 → '+relativeNotation(instrument,song.doKey||'C')+'</small></div>'}
  function songInstrumentSummary(song){const rows=(song.instrumentIds||[]).map(id=>byId(db.instruments,id)).filter(Boolean),melody=rows.filter(i=>i.family==='melodi'||i.family==='melodiTambahan'),bass=rows.filter(i=>i.family==='bass'),gajah=rows.filter(i=>i.family==='gajah'),chords=rows.filter(i=>i.family==='chord'),altam=rows.filter(i=>!['melodi','melodiTambahan','bass','gajah','chord'].includes(i.family)),parts=[];if(melody.length){const nums=melody.map(i=>Number(i.number)).filter(Number.isFinite);parts.push(nums.length?'Melodi '+Math.min(...nums)+'–'+Math.max(...nums)+' ('+melody.length+')':'Melodi ('+melody.length+')')}if(bass.length)parts.push('Bass g–f ('+bass.length+')');if(gajah.length)parts.push('Gajah G–F ('+gajah.length+')');if(chords.length)parts.push('Accomp: '+[...new Set(chords.map(i=>i.number).filter(Boolean))].join(', '));if(altam.length)parts.push('AlTam: '+altam.map(i=>i.name).join(', '));return '<div class="song-instrument-summary"><b>'+rows.length+' bagian instrumen</b><small>'+esc(parts.join(' · ')||'Belum ada instrumen yang dipilih.')+'</small></div>'}
  function bindPageEvents(){if($('#playerSearch'))$('#playerSearch').oninput=e=>{playerQuery=e.target.value;const pos=e.target.selectionStart;playersRefresh();$('#playerSearch')?.focus();$('#playerSearch')?.setSelectionRange(pos,pos)};if($('#songSearch'))$('#songSearch').oninput=e=>{songQuery=e.target.value;songRefresh()};$$('[data-filter]').forEach(b=>b.onclick=()=>{instrumentFilter=b.dataset.filter;render()});$$('[data-instrument-group]').forEach(b=>b.onclick=()=>{instrumentGroup=b.dataset.instrumentGroup;instrumentFilter='semua';render()});$$('[data-calendar-view]').forEach(b=>b.onclick=()=>{calendarView=b.dataset.calendarView;render()});if($('#prevMonth'))$('#prevMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);render()};if($('#nextMonth'))$('#nextMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);render()};if($('#todayMonth'))$('#todayMonth').onclick=()=>{month=new Date();render()};$$('.cal-day').forEach(d=>d.onclick=()=>openEventForm('',d.dataset.date));$$('.cal-event').forEach(el=>el.onclick=e=>{e.stopPropagation();const ev=byId(db.events,e.currentTarget.dataset.event);if(ev)showEvent(ev)})}
  function playersRefresh(){const q=$('#playerSearch')?.value||'';playerQuery=q;render();const input=$('#playerSearch');if(input){input.focus();input.setSelectionRange(q.length,q.length)}}function songRefresh(){const q=$('#songSearch')?.value||'';songQuery=q;render();const input=$('#songSearch');if(input){input.focus();input.setSelectionRange(q.length,q.length)}}
  function modal(title,body,submit,submitLabel='Simpan'){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="btn btn-icon" onclick="closeModal()">×</button></div><form id="modalForm"><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Batal</button><button type="submit" class="btn btn-primary">${submitLabel}</button></div></form></div></div>`;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};$('#modalForm').onsubmit=e=>{e.preventDefault();submit(new FormData(e.currentTarget))}}
  function closeModal(){$('#modalRoot').innerHTML=''}
  const inp=(label,name,value='',type='text',placeholder='')=>`<div class="form-field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}"></div>`;
  function openPlayerForm(id=''){const p=byId(db.players,id)||{name:'',section:'',email:'',phone:'',instrumentAssignments:{},notes:''};const options=db.instruments.map(i=>{const held=assignedQty(p,i.id),elsewhere=inventoryAssigned(i.id,p.id),available=Math.max(0,Number(i.quantity||1)-elsewhere),max=available+held;return `<label class="assignment-option"><input class="player-assignment" type="checkbox" name="assignment" value="${esc(i.id)}" ${held?'checked':''} ${!held&&!available?'disabled':''}><span><b>${esc(i.name)}</b><small>Persediaan ${Number(i.quantity||1)} · sudah dialokasikan ke pemain lain ${elsewhere} · tersedia ${available}</small></span><input class="assignment-quantity" name="qty__${esc(i.id)}" type="number" min="1" max="${Math.max(1,max)}" value="${held||1}" ${held?'':'disabled'} aria-label="Jumlah ${esc(i.name)}"></label>`}).join('');modal(id?'Edit pemain':'Tambah pemain',`<div class="form-grid">${inp('Nama lengkap *','name',p.name)}${inp('Bagian / suara','section',p.section,'text','Melodi, bass, perkusi…')}${inp('Email','email',p.email,'email')}${inp('Nomor telepon','phone',p.phone,'tel')}<div class="form-field full"><label>Instrumen yang dipegang / dimainkan · pilih lalu isi jumlah unit</label><div class="assignment-list">${options||'<span class="help-text">Tambahkan instrumen dahulu.</span>'}</div></div><div class="form-field full"><label>Catatan</label><textarea name="notes">${esc(p.notes||'')}</textarea></div></div>`,f=>{const name=f.get('name').trim();if(!name)return toast('Nama pemain perlu diisi.',true);const instrumentAssignments={};for(const instrumentId of f.getAll('assignment')){const qty=Number(f.get(`qty__${instrumentId}`)),instrument=byId(db.instruments,instrumentId),available=instrument?Number(instrument.quantity||1)-inventoryAssigned(instrumentId,p.id):0;if(!Number.isInteger(qty)||qty<1)return toast('Jumlah unit yang dipegang harus minimal 1.',true);if(qty>available)return toast(`${instrument?.name||'Instrumen'}: hanya ${available} unit yang tersedia untuk pemain ini.`,true);instrumentAssignments[instrumentId]=qty}const item={id:p.id||uid(),name,section:f.get('section').trim(),email:f.get('email').trim(),phone:f.get('phone').trim(),instrumentAssignments,notes:f.get('notes').trim()};const ix=db.players.findIndex(x=>x.id===item.id);if(ix>=0)db.players[ix]=item;else db.players.push(item);save();closeModal();render();toast('Data pemain tersimpan.')});$$('.player-assignment').forEach(check=>check.onchange=()=>{const qty=check.closest('.assignment-option').querySelector('.assignment-quantity');qty.disabled=!check.checked;if(check.checked&&!qty.value)qty.value=1})}
  function openInstrumentForm(id='',preset=''){const old=byId(db.instruments,id),i=old||{name:preset==='chord'?accompName('Besar','G'):'',family:preset||'altam',number:'',pitch:'',quantity:1,status:'tersedia',notes:''},families=[['melodi','Melodi 0–30'],['melodiTambahan','Melodi tambahan 31–35'],['bass','Bass'],['gajah','Gajah'],['chord','Accomp (Chord)'],['altam','Alat Tambahan (AlTam)']],options=families.map(x=>'<option value="'+x[0]+'" '+(i.family===x[0]?'selected':'')+'>'+x[1]+'</option>').join('');modal(id?'Edit instrumen':'Tambah instrumen','<div class="form-grid">'+inp('Nama instrumen *','name',i.name,'text',i.family==='chord'?'Contoh: Accomp Besar C7':i.family==='altam'?'Contoh: Contrabass, Violin, Gitar':'Contoh: Melodi 0, Bass g, Gajah G')+'<div class="form-field"><label>Kategori</label><select name="family">'+options+'</select></div>'+inp(i.family==='chord'?'Label akor':'Label / bagian','number',i.number,'text',i.family==='chord'?'Contoh: G, Dm, C7, Bb7':'Contoh: 0, g, G')+inp(i.family==='chord'?'Susunan nada / keterangan':'Nada acuan / tuning','pitch',i.pitch,'text',i.family==='chord'?'Contoh: C-E-G atau G-B-D-F':'Contoh: F#3, G2')+'<div class="form-field full"><span class="help-text">'+(i.family==='chord'?'Pilih nama Accomp Besar atau Accomp Kecil langsung pada nama instrumen. Satu unit adalah satu angklung pengiring berisi 3 tabung (triad) atau 4 tabung (akor 7). Pembagian instrumen dan jumlah unit per pemain dicatat di data pemain.':'Jumlah unit dalam persediaan dihitung per instrumen dengan label yang sama.')+'</span></div><div class="form-field"><label>Jumlah unit dalam persediaan</label><input name="quantity" type="number" min="1" max="99" value="'+esc(i.quantity||1)+'"><span class="help-text">Masukkan jumlah unit yang dimiliki untuk label ini.</span></div><div class="form-field"><label>Kondisi</label><select name="status"><option value="tersedia" '+(i.status==='tersedia'?'selected':'')+'>Tersedia</option><option value="dipinjam" '+(i.status==='dipinjam'?'selected':'')+'>Dipinjam</option><option value="perbaikan" '+(i.status==='perbaikan'?'selected':'')+'>Perlu perbaikan</option></select></div><div class="form-field full"><label>Catatan</label><textarea name="notes">'+esc(i.notes||'')+'</textarea></div></div>',f=>{if(!f.get('name').trim())return toast('Nama instrumen perlu diisi.',true);if(f.get('family')==='chord'&&!f.get('number').trim())return toast('Instrumen Accomp perlu label akor.',true);const quantity=Number(f.get('quantity')),assigned=inventoryAssigned(i.id);if(!Number.isInteger(quantity)||quantity<1||quantity>99)return toast('Jumlah unit harus antara 1 dan 99.',true);if(quantity<assigned)return toast('Jumlah tidak bisa kurang dari '+assigned+' unit yang sudah dipegang pemain.',true);const family=f.get('family'),item={id:i.id||uid(),name:f.get('name').trim(),family,number:f.get('number').trim(),pitch:f.get('pitch').trim(),quantity,status:f.get('status'),notes:f.get('notes').trim()};const ix=db.instruments.findIndex(x=>x.id===item.id);ix>=0?db.instruments[ix]=item:db.instruments.push(item);save();closeModal();render();toast('Instrumen tersimpan.')})}
  function openSongForm(id=''){const s=byId(db.songs,id)||{title:'',composer:'',genre:'',doKey:'C',scale:'diatonis',tempo:'',instrumentIds:[],notes:[],url:'',memo:''};const noteText=(s.notes||[]).map(n=>typeof n==='string'?n:[n.bar,n.text].filter(Boolean).join(' | ')).join('\n');const options=db.instruments.map(i=>`<label class="check-option"><input type="checkbox" name="instrumentIds" value="${i.id}" ${(s.instrumentIds||[]).includes(i.id)?'checked':''}><span>${esc(i.name)}<small>${esc(i.pitch||(i.family==='chord'?i.number:'—'))}</small></span></label>`).join('');modal(id?'Edit lagu':'Tambah lagu',`<div class="form-grid">${inp('Judul lagu *','title',s.title)}${inp('Komposer / sumber','composer',s.composer)}${inp('Genre / daerah','genre',s.genre)}<div class="form-field"><label>Nada Do=</label><select name="doKey">${tones.map(t=>`<option ${s.doKey===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-field"><label>Sistem nada</label><select name="scale"><option value="diatonis" ${s.scale==='diatonis'?'selected':''}>Diatonis</option><option value="slendro" ${s.scale==='slendro'?'selected':''}>Slendro</option><option value="pelog" ${s.scale==='pelog'?'selected':''}>Pelog</option><option value="lainnya" ${s.scale==='lainnya'?'selected':''}>Lainnya</option></select></div>${inp('Tempo (BPM)','tempo',s.tempo,'number','Contoh: 96')}<div class="form-field full"><label>Instrumen / bagian yang digunakan</label><div class="checkbox-list">${options||'<span class="help-text">Tambahkan instrumen dahulu.</span>'}</div></div><div class="form-field full"><label>Notasi angklung (satu baris per birama/frasa)</label><textarea name="notes" placeholder="Contoh:\n1 | Do Re Mi — Mi Re Do\n2 | Sol Sol La Sol — Mi\nCatat notasi angka, solmisasi, atau petunjuk pemain.">${esc(noteText)}</textarea><span class="help-text">Notasi pemain tampil sebagai angka relatif terhadap Do=. Gunakan / untuk kromatis naik, \\ untuk kromatis turun, ^ untuk oktaf atas, dan . untuk oktaf bawah. Contoh Do=C: C#=1/, Db=2\\, C5=1^, C3=1..</span></div>${inp('Tautan / lokasi partitur','url',s.url,'url','https://…')}<div class="form-field full"><label>Catatan latihan</label><textarea name="memo">${esc(s.memo||'')}</textarea></div></div>`,f=>{if(!f.get('title').trim())return toast('Judul lagu perlu diisi.',true);const item={id:s.id||uid(),title:f.get('title').trim(),composer:f.get('composer').trim(),genre:f.get('genre').trim(),doKey:f.get('doKey'),scale:f.get('scale'),tempo:f.get('tempo'),instrumentIds:f.getAll('instrumentIds'),notes:f.get('notes').split('\n').map(x=>x.trim()).filter(Boolean),url:f.get('url').trim(),memo:f.get('memo').trim()};const ix=db.songs.findIndex(x=>x.id===item.id);ix>=0?db.songs[ix]=item:db.songs.push(item);save();closeModal();render();toast('Lagu dan notasi tersimpan.')})}
  function openEventForm(id='',date=today()){const e=byId(db.events,id)||{title:'',date,time:'',location:'',type:'rehearsal',description:'',attendance:{},recurrence:null},frequency=e.recurrence?.frequency||'',until=e.recurrence?.until||addMonthsISO(e.date||date,3),options=[['','Tidak berulang'],['weekly','Setiap minggu'],['biweekly','Setiap 2 minggu'],['monthly','Setiap bulan']].map(x=>'<option value="'+x[0]+'" '+(frequency===x[0]?'selected':'')+'>'+x[1]+'</option>').join('');modal(id?'Edit agenda':'Tambah agenda','<div class="form-grid">'+inp('Nama agenda *','title',e.title)+inp('Tanggal *','date',e.date||date,'date')+'<div class="form-field"><label>Jenis agenda</label><select name="type"><option value="rehearsal" '+(e.type==='rehearsal'?'selected':'')+'>Latihan</option><option value="performance" '+(e.type==='performance'?'selected':'')+'>Penampilan</option><option value="other" '+(e.type==='other'?'selected':'')+'>Agenda</option></select></div>'+inp('Waktu','time',e.time,'time')+inp('Lokasi','location',e.location)+'<div class="form-field"><label>Ulangi</label><select name="recurrence">'+options+'</select></div>'+inp('Ulangi sampai tanggal','repeatUntil',until,'date')+'<div class="form-field full"><span class="help-text">Pilih tanggal akhir untuk jadwal berulang. Absensi setiap tanggal dicatat terpisah. Saat mengedit agenda berulang, perubahan diterapkan ke tanggal ini dan jadwal berikutnya dalam seri.</span></div><div class="form-field full"><label>Catatan</label><textarea name="description">'+esc(e.description||'')+'</textarea></div></div>',f=>{const title=f.get('title').trim(),newDate=f.get('date'),repeat=f.get('recurrence'),repeatUntil=f.get('repeatUntil');if(!title||!newDate)return toast('Nama agenda dan tanggal perlu diisi.',true);if(repeat&&(!repeatUntil||repeatUntil<newDate))return toast('Tanggal akhir pengulangan harus sama atau setelah tanggal agenda.',true);const item={id:e.id||uid(),title,date:newDate,time:f.get('time'),location:f.get('location').trim(),type:f.get('type'),description:f.get('description').trim(),attendance:e.attendance||{}},seriesId=e.recurrence?.seriesId||uid(),preserve=e.recurrence?.seriesId?db.events.filter(x=>x.recurrence?.seriesId===seriesId):[];if(e.recurrence?.seriesId){db.events=db.events.filter(x=>x.recurrence?.seriesId!==seriesId||x.date<e.date)}else if(id){db.events=db.events.filter(x=>x.id!==id)}if(repeat){db.events.push(...eventSeries(item,repeat,repeatUntil,seriesId,preserve))}else{item.recurrence=null;db.events.push(item)}save();month=new Date(newDate+'T12:00:00');closeModal();render();toast(repeat?'Jadwal berulang tersimpan.':'Agenda tersimpan.')})}
  function openOrchestraForm(){modal('Informasi orchestra',`<div class="form-grid">${inp('Nama orchestra *','name',db.orchestra.name)}${inp('Konduktor / pengelola','conductor',db.orchestra.conductor)}<div class="form-field full">${inp('Lokasi utama','location',db.orchestra.location)}</div></div>`,f=>{if(!f.get('name').trim())return toast('Nama orchestra perlu diisi.',true);db.orchestra={name:f.get('name').trim(),conductor:f.get('conductor').trim(),location:f.get('location').trim()};save();closeModal();render();toast('Informasi orchestra diperbarui.')})}
  function openQuickAdd(){modal('Tambah data ke orchestra',`<div class="data-grid"><button type="button" class="btn btn-quiet" onclick="closeModal();openPlayerForm()">♧ &nbsp;Pemain</button><button type="button" class="btn btn-quiet" onclick="closeModal();openInstrumentForm()">♫ &nbsp;Instrumen</button><button type="button" class="btn btn-quiet" onclick="closeModal();openSongForm()">▤ &nbsp;Lagu</button><button type="button" class="btn btn-quiet" onclick="closeModal();openEventForm()">▦ &nbsp;Jadwal</button></div>`,()=>{},'Tutup');$('#modalForm button[type=submit]').textContent='Tutup'}
  function editBankNotes(){let mel=db.instruments.filter(i=>i.family==='melodi').sort((a,b)=>a.number-b.number);let body=`<p class="help-text">Nomor standar memakai scientific pitch notation: Melodi 0 = F#3, 6 = C4, 18 = C5, dan 30 = C6. Nilai dapat disesuaikan jika set orchestra Anda memakai acuan berbeda.</p><div style="max-height:48vh;overflow:auto"><div class="note-grid">${mel.map(i=>`<label class="note-cell"><b>${esc(i.name)}</b><input name="${i.id}" value="${esc(i.pitch||'')}" aria-label="Nada untuk ${esc(i.name)}" style="width:100%;margin-top:8px;text-align:center;padding:6px"></label>`).join('')}</div></div>`;modal('Peta nada ilmiah · Melodi 0–30',body,f=>{mel.forEach(i=>i.pitch=f.get(i.id).trim());save();closeModal();render();toast('Nada acuan diperbarui.')})}
  function viewSong(id){const s=byId(db.songs,id);if(!s)return;modal(esc(s.title),`<div class="form-grid"><div><div class="eyebrow">KOMPOSER</div><p>${esc(s.composer||'—')}</p></div><div><div class="eyebrow">NADA DASAR</div><p><span class="pill gold">Do=${esc(s.doKey)}4 · ${esc(s.scale)}</span></p><small class="pitch-legend">/ = naik kromatis, \\ = turun kromatis; ^ = oktaf atas, . = oktaf bawah. Contoh Do=C: C# = 1/, Db = 2\\, C5 = 1^, C3 = 1..</small></div><div><div class="eyebrow">INSTRUMEN / RENTANG</div>${songInstrumentSummary(s)}</div><div><div class="eyebrow">TEMPO</div><p>${esc(s.tempo||'—')} BPM</p></div><div class="form-field full"><div class="eyebrow">NOTASI</div><div class="song-notes">${esc((s.notes||[]).map((n,i)=>`${String(i+1).padStart(2,'0')}  ${typeof n==='string'?n:n.text||''}`).join('\n')||'Belum ada notasi.')}</div></div>${s.memo?`<div class="form-field full"><div class="eyebrow">CATATAN</div><p>${esc(s.memo)}</p></div>`:''}${s.url?`<div class="form-field full"><a href="${esc(s.url)}" target="_blank" rel="noopener">Buka partitur ↗</a></div>`:''}</div>`,()=>closeModal(),'Tutup');$('#modalForm button[type=submit]').textContent='Tutup'}
  function showEvent(e){modal(esc(e.title),`<div class="form-grid"><div><div class="eyebrow">TANGGAL</div><p>${prettyDate(e.date)}</p></div><div><div class="eyebrow">JENIS</div><p>${eventType(e.type)}</p></div><div><div class="eyebrow">WAKTU</div><p>${esc(e.time||'—')}</p></div><div><div class="eyebrow">LOKASI</div><p>${esc(e.location||'—')}</p></div><div class="form-field full"><div class="eyebrow">KEHADIRAN</div><p>${esc(attendanceSummary(e))}</p></div>${e.description?`<div class="form-field full"><div class="eyebrow">CATATAN</div><p>${esc(e.description)}</p></div>`:''}</div>`,()=>closeModal(),'Tutup');const foot=$('.modal-foot');foot.insertAdjacentHTML('afterbegin',`<button type="button" class="btn btn-primary" onclick="closeModal();openAttendance('${e.id}')">Absensi</button><button type="button" class="btn btn-quiet" onclick="closeModal();openEventForm('${e.id}')">Edit agenda</button>`);}
  function openAttendance(eventId){const e=byId(db.events,eventId);if(!e)return;if(!db.players.length)return toast('Tambahkan pemain terlebih dahulu untuk mengisi absensi.',true);const statuses=[['hadir','Hadir'],['izin','Izin'],['sakit','Sakit'],['alpa','Alpa'],['belum','Belum diisi']];const rows=db.players.map(p=>`<div class="attendance-row"><div><b>${esc(p.name)}</b><small>${esc(p.section||'Anggota orchestra')}</small></div><select name="att_${esc(p.id)}">${statuses.map(s=>`<option value="${s[0]}" ${(e.attendance?.[p.id]||'belum')===s[0]?'selected':''}>${s[1]}</option>`).join('')}</select></div>`).join('');modal('Absensi · '+esc(e.title),`<p class="help-text">${esc(prettyDate(e.date))} · Pilih status untuk setiap pemain. Absensi disimpan pada agenda ini.</p><div class="attendance-list">${rows}</div>`,f=>{const attendance={};db.players.forEach(p=>{const value=f.get('att_'+p.id);if(value&&value!=='belum')attendance[p.id]=value});e.attendance=attendance;save();closeModal();render();toast('Absensi tersimpan.')})}
  function del(arr,id,label){if(!confirm(`Hapus ${label} ini?`))return;const index=arr.findIndex(x=>x.id===id);if(index>=0)arr.splice(index,1);if(arr===db.players)db.events.forEach(e=>{if(e.attendance)delete e.attendance[id]});if(arr===db.instruments){db.players.forEach(p=>{if(p.instrumentAssignments)delete p.instrumentAssignments[id];if(p.instrumentIds)p.instrumentIds=p.instrumentIds.filter(x=>x!==id)});db.songs.forEach(s=>s.instrumentIds=(s.instrumentIds||[]).filter(x=>x!==id))}save();render();toast(`${label} dihapus.`)}
  function deletePlayer(id){del(db.players,id,'Pemain')}function deleteInstrument(id){del(db.instruments,id,'Instrumen')}function deleteSong(id){del(db.songs,id,'Lagu')}function deleteEvent(id){del(db.events,id,'Agenda')}
  function download(filename,content,mime){const blob=new Blob([content],{type:mime});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
  function exportJSON(){download(slug(db.orchestra.name)+'-cadangan.json',JSON.stringify(db,null,2),'application/json;charset=utf-8');toast('Cadangan JSON diunduh.')}
  function slug(s){return (s||'orchestra-angklung').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'orchestra-angklung'}
  function xmlEsc(s){return String(s??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]))}
  function xmlTag(name,v,attrs=''){return `<${name}${attrs}>${xmlEsc(v)}</${name}>`}
  function exportXML(){let x='<?xml version="1.0" encoding="UTF-8"?>\n<rumpun version="9">\n';x+='  <orchestra><name>'+xmlEsc(db.orchestra.name)+'</name><conductor>'+xmlEsc(db.orchestra.conductor)+'</conductor><location>'+xmlEsc(db.orchestra.location)+'</location></orchestra>\n  <players>\n';db.players.forEach(p=>{x+='    <player id="'+xmlEsc(p.id)+'"><name>'+xmlEsc(p.name)+'</name><section>'+xmlEsc(p.section)+'</section><email>'+xmlEsc(p.email)+'</email><phone>'+xmlEsc(p.phone)+'</phone><notes>'+xmlEsc(p.notes)+'</notes><assignments>'+Object.entries(p.instrumentAssignments||{}).map(([id,quantity])=>'<instrumentAssignment ref="'+xmlEsc(id)+'" quantity="'+xmlEsc(quantity)+'"/>').join('')+'</assignments></player>\n'});x+='  </players>\n  <instruments>\n';db.instruments.forEach(i=>{x+='    <instrument id="'+xmlEsc(i.id)+'" family="'+xmlEsc(i.family)+'"><name>'+xmlEsc(i.name)+'</name><number>'+xmlEsc(i.number)+'</number><pitch>'+xmlEsc(i.pitch)+'</pitch><quantity>'+xmlEsc(i.quantity||1)+'</quantity><status>'+xmlEsc(i.status)+'</status><notes>'+xmlEsc(i.notes)+'</notes></instrument>\n'});x+='  </instruments>\n  <songs>\n';db.songs.forEach(s=>{x+='    <song id="'+xmlEsc(s.id)+'"><title>'+xmlEsc(s.title)+'</title><composer>'+xmlEsc(s.composer)+'</composer><genre>'+xmlEsc(s.genre)+'</genre><do>'+xmlEsc(s.doKey)+'</do><scale>'+xmlEsc(s.scale)+'</scale><tempo>'+xmlEsc(s.tempo)+'</tempo><url>'+xmlEsc(s.url)+'</url><memo>'+xmlEsc(s.memo)+'</memo><instruments>'+(s.instrumentIds||[]).map(id=>'<instrumentRef>'+xmlEsc(id)+'</instrumentRef>').join('')+'</instruments><notation>'+(s.notes||[]).map((n,i)=>'<line bar="'+(i+1)+'">'+xmlEsc(typeof n==='string'?n:n.text||'')+'</line>').join('')+'</notation></song>\n'});x+='  </songs>\n  <calendar>\n';db.events.forEach(e=>{x+='    <event id="'+xmlEsc(e.id)+'" type="'+xmlEsc(e.type)+'"'+(e.recurrence?' series="'+xmlEsc(e.recurrence.seriesId)+'" frequency="'+xmlEsc(e.recurrence.frequency)+'" until="'+xmlEsc(e.recurrence.until)+'" occurrence="'+xmlEsc(e.recurrence.index)+'"':'')+'><title>'+xmlEsc(e.title)+'</title><date>'+xmlEsc(e.date)+'</date><time>'+xmlEsc(e.time)+'</time><location>'+xmlEsc(e.location)+'</location><description>'+xmlEsc(e.description)+'</description><attendance>'+Object.entries(e.attendance||{}).map(([playerId,status])=>'<mark playerRef="'+xmlEsc(playerId)+'" status="'+xmlEsc(status)+'"/>').join('')+'</attendance></event>\n'});x+='  </calendar>\n</rumpun>\n';download(slug(db.orchestra.name)+'-rumpun.xml',x,'application/xml;charset=utf-8');toast('Berkas XML orchestra diunduh.')}
  function xmlToData(text){const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error('Format XML tidak valid.');const root=doc.documentElement;if(root.tagName!=='rumpun')throw Error('XML bukan berkas Rumpun.');const get=(el,sel)=>el.querySelector(sel)?.textContent||'',all=(el,sel)=>[...el.querySelectorAll(':scope > '+sel)];const out=fresh(),o=root.querySelector('orchestra');out.version=Number(root.getAttribute('version'))||1;out.orchestra={name:get(o,'name')||out.orchestra.name,conductor:get(o,'conductor'),location:get(o,'location')};out.instruments=all(root.querySelector('instruments')||root,'instrument').map(i=>({id:i.getAttribute('id')||uid(),family:i.getAttribute('family')||'altam',name:get(i,'name'),number:get(i,'number'),pitch:get(i,'pitch'),quantity:Number(get(i,'quantity'))||1,status:get(i,'status')||'tersedia',notes:get(i,'notes')}));out.players=all(root.querySelector('players')||root,'player').map(p=>{const assignments={};all(p.querySelector('assignments')||p,'instrumentAssignment').forEach(a=>assignments[a.getAttribute('ref')]=Number(a.getAttribute('quantity'))||1);if(!Object.keys(assignments).length)all(p.querySelector('instruments')||p,'instrumentRef').forEach(r=>assignments[r.textContent]=1);return {id:p.getAttribute('id')||uid(),name:get(p,'name'),section:get(p,'section'),email:get(p,'email'),phone:get(p,'phone'),notes:get(p,'notes'),instrumentAssignments:assignments}});out.songs=all(root.querySelector('songs')||root,'song').map(s=>({id:s.getAttribute('id')||uid(),title:get(s,'title'),composer:get(s,'composer'),genre:get(s,'genre'),doKey:get(s,'do')||'C',scale:get(s,'scale')||'diatonis',tempo:get(s,'tempo'),url:get(s,'url'),memo:get(s,'memo'),instrumentIds:all(s.querySelector('instruments')||s,'instrumentRef').map(r=>r.textContent),notes:all(s.querySelector('notation')||s,'line').map(n=>n.textContent)}));out.events=all(root.querySelector('calendar')||root,'event').map(e=>({id:e.getAttribute('id')||uid(),type:e.getAttribute('type')||'rehearsal',title:get(e,'title'),date:get(e,'date'),time:get(e,'time'),location:get(e,'location'),description:get(e,'description'),recurrence:e.getAttribute('frequency')?{seriesId:e.getAttribute('series'),frequency:e.getAttribute('frequency'),until:e.getAttribute('until'),index:Number(e.getAttribute('occurrence'))||0}:null,attendance:Object.fromEntries(all(e.querySelector('attendance')||e,'mark').map(m=>[m.getAttribute('playerRef'),m.getAttribute('status')]))}));return out}
  $('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text();const imported=file.name.toLowerCase().endsWith('.xml')?xmlToData(text):JSON.parse(text);if(!imported||!Array.isArray(imported.players)||!Array.isArray(imported.instruments)||!Array.isArray(imported.songs)||!Array.isArray(imported.events))throw Error('Struktur cadangan tidak lengkap.');if(!confirm('Impor akan menggantikan seluruh data yang tersimpan di browser ini. Lanjutkan?'))return;db=upgradeData(imported);save();render();toast('Data orchestra berhasil dipulihkan.')}catch(err){toast(err.message||'Berkas tidak dapat dibaca.',true)}finally{e.target.value=''}};
  document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){setPage(nav.dataset.page);return}if(e.target.id==='menuToggle')$('#sidebar').classList.toggle('open')});
  window.setPage=setPage;window.openPlayerForm=openPlayerForm;window.openInstrumentForm=openInstrumentForm;window.openSongForm=openSongForm;window.openEventForm=openEventForm;window.openAttendance=openAttendance;window.openQuickAdd=openQuickAdd;window.openOrchestraForm=openOrchestraForm;window.editBankNotes=editBankNotes;window.viewSong=viewSong;window.exportXML=exportXML;window.exportJSON=exportJSON;window.closeModal=closeModal;window.deletePlayer=deletePlayer;window.deleteInstrument=deleteInstrument;window.deleteSong=deleteSong;window.deleteEvent=deleteEvent;
  $('#themeToggle').onclick=toggleTheme;
  render();
})();
